int x = 5;
int* p = &x;     // holds x's address
int& r = x;      // another name for x
int&& rr = 10;   // binds to a temporary

// int& bad = 10;    error: 10 is an rvalue
// int&& bad2 = x;   error: x is an lvalue
int&& ok = std::move(x);  // cast to rvalue

void f(int&)  { std::cout << "lvalue\n"; }
void f(int&&) { std::cout << "rvalue\n"; }

int main() {
    int x = 1;
    f(x);             // lvalue
    f(42);            // rvalue
    f(std::move(x));  // rvalue
    int&& rr = 5;
    f(rr);            // lvalue!
}
